/// <summary>
///     The <c>AVABPTrackingProspectsController</c> class is the controller class for <c>Tracking prospects</c>
/// </summary>
internal final class AVABPTrackingProspectsController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVABPTrackingProspectsController controller;
    /*
    controller = new AVABPTrackingProspectsController(  classStr(AVABPTrackingProspectsService),
                                                        methodStr(AVABPTrackingProspectsService, startOperation),
                                                        SysOperationExecutionMode::Synchronous                      );
    */
    controller = new AVABPTrackingProspectsController();
    controller.parmShowDialog(true);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.parmInBatch(false);
    controller.batchInfo().fieldBatchExecuteValue(false);
    controller.showBatchTab(false);
    controller.parmLoadFromSysLastValue(true);
    controller.startOperation();
}

/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmDialogCaption("@NDX:NXABPTrackingProspect");
    this.parmClassName(classStr(AVABPTrackingProspectsService));
    this.parmMethodName(methodStr(AVABPTrackingProspectsService, startOperation));
}

/// <summary>
///     AVA <c>defaultCaption</c> method.
/// </summary>
/// <returns>
///     <c>ClassDescription</c> as return value
/// </returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXABPTrackingProspectHelp";
}

/// <summary>
///     AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVABPTrackingProspectsController</c> as return value
/// </returns>
public static AVABPTrackingProspectsController newFromArgs(Args _args)
{
    AVABPTrackingProspectsController    controller;
    AVABPTrackingProspectsContract      contract;
    SysDictMethod                       dictMethod;
    MenuFunction                        callerMenuItem;
    str                                 contractParameterName;

    controller = new AVABPTrackingProspectsController();
    controller.initializeFromArgs(_args);
    // nice way to get the "_contract" name of the parameter:
    dictMethod = new SysDictMethod(UtilElementType::ClassInstanceMethod, className2Id(controller.parmClassName()), controller.parmMethodName());
    contractParameterName = dictMethod.parameterName(1);

    contract = controller.getDataContractObject(contractParameterName);

    if (_args)
    {
        callerMenuItem = new MenuFunction(_args.menuItemName(), _args.menuItemType());
        if (callerMenuItem)
        {
            controller.parmDialogCaption(callerMenuItem.label());
        }
    }

    contract.initQuery();
    //Important to call queryChanged!
    controller.queryChanged(strFmt('%1.parmPackedQuery', contractParameterName), contract.getQuery());
    controller.parmLoadFromSysLastValue(true);

    return controller;
}
